(function(root,factory){if(typeof module==='object')module.exports=factory(require('./persistencia_rdo'),require('./vendas_obras'));else root.MartinsOrcamentos=factory(root.MartinsPersistenciaRdo,root.MartinsVendasObras);})(globalThis,(P,V)=>{'use strict';
function text(value,label,required=false,max=2000){const s=String(value??'').trim();if(required&&!s||s.length>max)throw Error('Confira '+label+' (até '+max+' caracteres)');return s;}
function lines(rows){if(!Array.isArray(rows)||!rows.length||rows.length>200)throw Error('Adicione de 1 a 200 itens');return rows.map((row,i)=>{const qtd=Number(row.qtd),price=Number(row.precoUnit),cents=Math.round(price*100);if(row.qtd===''||row.precoUnit===''||!Number.isFinite(qtd)||qtd<=0||qtd>1000000||!Number.isFinite(price)||price<0||!Number.isSafeInteger(cents)||Math.abs(price*100-cents)>.00001)throw Error('Item '+(i+1)+': quantidade positiva e preço não negativo com até 2 casas decimais');const total=Math.round(qtd*price*100)/100;if(!Number.isFinite(total)||!Number.isSafeInteger(Math.round(total*100)))throw Error('Total do item fora do limite');return {...structuredClone(row),desc:text(row.desc,'descrição do item '+(i+1),true,500),unid:text(row.unid,'unidade do item '+(i+1),true,30),qtd,precoUnit:price,total};});}
function create(rows,input,actor,{id='ORC-'+P.newId(),now=new Date().toISOString()}={}){if(!Array.isArray(rows)||rows.some(q=>q.id===id))throw Error('Identificação de orçamento já utilizada');const itens=lines(input.itens),total=itens.reduce((n,r)=>n+Math.round(r.total*100),0)/100;if(!Number.isFinite(total)||!Number.isSafeInteger(Math.round(total*100)))throw Error('Total do orçamento fora do limite');const day=P.brDay(new Date(now)),year=day.slice(0,4),seq=Math.max(0,...rows.filter(q=>String(q.num||'').endsWith('/'+year)).map(q=>Number(/^(\d+)\//.exec(q.num||'')?.[1]||0)))+1;const quote={id,num:String(seq).padStart(3,'0')+'/'+year,empresa:text(input.empresa,'empresa',true,200),cliente:text(input.cliente,'cliente',true,200),data:day,status:'Orçamento Aberto',itens,total,validade:text(input.validade,'validade'),condicoes:text(input.condicoes,'condições'),prazo:text(input.prazo,'prazo'),objeto:text(input.objeto,'objeto'),observacoes:text(input.observacoes,'observações'),clienteDetalhe:{doc:text(input.clienteDetalhe?.doc,'documento',false,100),tel:text(input.clienteDetalhe?.tel,'telefone',false,100),cidade:text(input.clienteDetalhe?.cidade,'cidade',false,200)},criadoPor:text(actor,'responsável',true,200),criadoEm:now};V.validate(quote);return {quote,rows:[quote,...structuredClone(rows)]};}
return {lines,create};});
